#!/bin/sh
# Xcode Cloud runs this after cloning (D-119, #265). The app's API code is
# generated by the swift-openapi-generator package plugin; our own builds
# pass -skipPackagePluginValidation, and Xcode Cloud needs the same trust
# set in Xcode's defaults before it builds.
set -e
defaults write com.apple.dt.Xcode IDESkipPackagePluginFingerprintValidatation -bool YES
defaults write com.apple.dt.Xcode IDESkipMacroFingerprintValidation -bool YES
